(5480520, 790101, 15711, '<td valign="top">I like this very much. Maybe my fav of the challenge.  Simple and emotive. The upturned book really is a nice touch.</td>', 'I like this very much. Maybe my fav of the challenge.  Simple and emotive. The upturned book really is a nice touch.', '2009-05-11 11:27:02.000000', NULL, 1),
(5480521, 789985, 15711, '<td valign="top">I like the intense colors. She''s climbing that couch! LOL</td>', 'I like the intense colors. She''s climbing that couch! LOL', '2009-05-11 11:27:38.000000', NULL, 1),
(5480525, 789920, 15711, '<td valign="top">Love the nostalgic feel of this one.</td>', 'Love the nostalgic feel of this one.', '2009-05-11 11:28:19.000000', NULL, 1),
(5480526, 790124, 15711, '<td valign="top">That''s totally about the cat but darn, the focus is perfect. 7</td>', 'That''s totally about the cat but darn, the focus is perfect. 7', '2009-05-11 11:29:32.000000', NULL, 1),
(5480527, 788792, 15711, '<td valign="top">How on earth did you get that chair up there? LOL  Lovely scene and unexpected.</td>', 'How on earth did you get that chair up there? LOL  Lovely scene and unexpected.', '2009-05-11 11:29:54.000000', NULL, 1),
(5480528, 789617, 15711, '<td valign="top">I love the centering and simpleness of this shot.  Nicely converted with the sepia. 8</td>', 'I love the centering and simpleness of this shot.  Nicely converted with the sepia. 8', '2009-05-11 11:30:20.000000', NULL, 1),
