(5480538, 788261, 15711, '<td valign="top">Beautiful.  The chair almost takes on human emotion. 8</td>', 'Beautiful.  The chair almost takes on human emotion. 8', '2009-05-11 11:33:01.000000', NULL, 1),
(5480540, 789997, 15711, '<td valign="top">Terrific use of light.  Perfect use of symmetry too with the doggy slightly offsetting that overall feel.  Probably my favorite so far.</td>', 'Terrific use of light.  Perfect use of symmetry too with the doggy slightly offsetting that overall feel.  Probably my favorite so far.', '2009-05-11 11:33:55.000000', NULL, 1),
(5480542, 789910, 15711, '<td valign="top">This has a nice stock/commercial quality.  Perfect focus.</td>', 'This has a nice stock/commercial quality.  Perfect focus.', '2009-05-11 11:34:48.000000', NULL, 1),
(5480564, 790101, 106256, '<td valign="top">My personal favourite entry for this theme.</td>', 'My personal favourite entry for this theme.', '2009-05-11 12:03:40.000000', NULL, 1),
(5480599, 789997, 70000, '<td valign="top">Awwww. I like this angle, it is a nice compliment to the last challenge</td>', 'Awwww. I like this angle, it is a nice compliment to the last challenge', '2009-05-11 12:23:43.000000', NULL, 1),
(5480611, 790085, 16106, '<td valign="top">This has a very nice 1970''s look, like something out of the photorealism school of painting, dense and layered. A nicely though out shot, That I would expect to do terribly here at DPC, but we can only hope. Good work.</td>', 'This has a very nice 1970''s look, like something out of the photorealism school of painting, dense and layered. A nicely though out shot, That I would expect to do terribly here at DPC, but we can only hope. Good work.', '2009-05-11 12:30:01.000000', NULL, 1),
(5480621, 789985, 70661, '<td valign="top">Very cool! I love all the colors.</td>', 'Very cool! I love all the colors.', '2009-05-11 12:41:49.000000', NULL, 1),
(5480625, 790105, 16106, '<td valign="top">This is a very lovely shot with a couple of flaws. The colors and mood are perfect, the stillness of the chair contrasting with the blurred action of the waves is great.<br/>What troubles me is the framing which cuts off the legs of the chair, and the sun''s reflection on the sand which blurs the line of the seat, as it has the same tones and luminance. Without those flaws it would be my top ribbon pick, with them it is merely very good.</td>', 'This is a very lovely shot with a couple of flaws. The colors and mood are perfect, the stillness of the chair contrasting with the blurred action of the waves is great.What troubles me is the framing which cuts off the legs of the chair, and the sun''s reflection on the sand which blurs the line of the seat, as it has the same tones and luminance. Without those flaws it would be my top ribbon pick, with them it is merely very good.', '2009-05-11 12:44:46.000000', NULL, 1),
(5480635, 789562, 70661, '<td valign="top">Love the vintage look of this one.</td>', 'Love the vintage look of this one.', '2009-05-11 12:49:31.000000', NULL, 1),
(5480731, 789507, 81530, '<td valign="top">Lovely</td>', 'Lovely', '2009-05-11 14:30:57.000000', NULL, 1),
(5480737, 789405, 81530, '<td valign="top">Lovely reflections.</td>', 'Lovely reflections.', '2009-05-11 14:35:17.000000', NULL, 1),
(5480738, 789985, 81530, '<td valign="top">Love the colours and the way the wall is painted.</td>', 'Love the colours and the way the wall is painted.', '2009-05-11 14:35:42.000000', NULL, 1),
(5480756, 790070, 52130, '<td valign="top">damn you! this was my idea, but I didn''t have time to make it out there. Oh well, nicely done and I love the pigeon :)</td>', 'damn you! this was my idea, but I didn''t have time to make it out there. Oh well, nicely done and I love the pigeon :)', '2009-05-11 14:51:22.000000', NULL, 1),
