INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5484379, 788802, 83313, '<td valign="top">I like the tones rendered here by what I assume was Topaz. The composition is not totally leading my eye though. Maybe just a bit on the busy side for this pixel size. Not totally sure.</td>', 'I like the tones rendered here by what I assume was Topaz. The composition is not totally leading my eye though. Maybe just a bit on the busy side for this pixel size. Not totally sure.', '2009-05-13 14:31:01.000000', NULL, 1),
(5484386, 788882, 83313, '<td valign="top">Maybe needed just a touch of clarify or Topaz to bring out all the nice textures and lighting in this. It does have a nice eye-leading perspective. (No vote, comment only)</td>', 'Maybe needed just a touch of clarify or Topaz to bring out all the nice textures and lighting in this. It does have a nice eye-leading perspective. (No vote, comment only)', '2009-05-13 14:33:11.000000', NULL, 1),
(5484388, 789678, 83313, '<td valign="top">Seems a bit flat and grainy in the background. I like the subject and perspective on them.</td>', 'Seems a bit flat and grainy in the background. I like the subject and perspective on them.', '2009-05-13 14:34:21.000000', NULL, 1),
(5484392, 790070, 83313, '<td valign="top">You must have known exactly where to go to find this piece of artwork.</td>', 'You must have known exactly where to go to find this piece of artwork.', '2009-05-13 14:35:49.000000', NULL, 1),
(5484395, 790072, 83313, '<td valign="top">I like what the b/w did for this. It draws my eye in nicely. Maybe could have used some selective noise reduction in a couple of areas. (No vote, comment only)</td>', 'I like what the b/w did for this. It draws my eye in nicely. Maybe could have used some selective noise reduction in a couple of areas. (No vote, comment only)', '2009-05-13 14:37:53.000000', NULL, 1),
(5484398, 789933, 83313, '<td valign="top">I can''t even figure out what I am looking at here. A melted plastic chair? Still an appealing abstract to me.</td>', 'I can''t even figure out what I am looking at here. A melted plastic chair? Still an appealing abstract to me.', '2009-05-13 14:39:43.000000', NULL, 1),
(5484401, 789846, 83313, '<td valign="top">Nice strong b/w work and an interesting looking piece of furniture. I''m curious to see your description of this item after the challenge.</td>', 'Nice strong b/w work and an interesting looking piece of furniture. I''m curious to see your description of this item after the challenge.', '2009-05-13 14:41:28.000000', NULL, 1),
(5484405, 789141, 83313, '<td valign="top">Just not doing much for me. Not sure if is the lighting, or the composition or what. The way the arm is cut off a bit at the frame edge does not quite work for me.</td>', 'Just not doing much for me. Not sure if is the lighting, or the composition or what. The way the arm is cut off a bit at the frame edge does not quite work for me.', '2009-05-13 14:43:38.000000', NULL, 1),
(5484409, 789405, 83313, '<td valign="top">Maybe a little too strong on the PP for me. I think it''s the way it made the water look that is the prob. It''s neat looking, but I also find it overpowering.</td>', 'Maybe a little too strong on the PP for me. I think it''s the way it made the water look that is the prob. It''s neat looking, but I also find it overpowering.', '2009-05-13 14:45:29.000000', NULL, 1),
(5484410, 790119, 83313, '<td valign="top">Comes off to me as very busy but not enough detail visible in it either. Lots of heavy dark areas that just swallow that detail.</td>', 'Comes off to me as very busy but not enough detail visible in it either. Lots of heavy dark areas that just swallow that detail.', '2009-05-13 14:47:01.000000', NULL, 1),
(5484413, 790106, 83313, '<td valign="top">Makes me want to sit down for a spell, enjoying a beer and watching the world go by. Love the detail, tones and colors.</td>', 'Makes me want to sit down for a spell, enjoying a beer and watching the world go by. Love the detail, tones and colors.', '2009-05-13 14:49:49.000000', NULL, 1),
(5484417, 790028, 83313, '<td valign="top">Seems a bit cramped in the frame for my preference. Except for the chair, everything else seems squeezed in around the edges.</td>', 'Seems a bit cramped in the frame for my preference. Except for the chair, everything else seems squeezed in around the edges.', '2009-05-13 14:50:54.000000', NULL, 1),
